custom_qss:
/* ============================================================
   STATIC — messy by design. Every surface clashes axes.
   Ink/teal base. Coral + chartreuse accents.
   ============================================================ */

* {
    border: none;
    background-color: transparent !important;
    color: #d8e8e2 !important;
}

QAbstractScrollArea, QFrame, QStackedWidget, QScrollArea, QTabWidget, QWidget {
    background: transparent !important;
    border: none;
}

/* ---------- window: long diagonal teal drift ---------- */
QMainWindow {
    background: qlineargradient(x1:0, y1:0, x2:0.7, y2:0.5,
        stop:0 #0e2a30, stop:0.3 #0b1f26, stop:0.55 #081a1e,
        stop:0.8 #0b2620, stop:1 #07141a) !important;
    border-top: 2px solid #c8f542;
}
QDialog {
    background: qlineargradient(x1:0.3, y1:0, x2:0.9, y2:1,
        stop:0 #0e2a30, stop:0.4 #08222a, stop:1 #07141a) !important;
    border-top: 2px solid #ff6f61;
}

/* ---------- menubar: flat strip ---------- */
QMenuBar {
    background: #0a1a1e !important;
    border-bottom: 1px solid #12333a;
}
QMenuBar::item {
    padding: 5px 12px;
    border-radius: 4px;
    background: transparent !important;
    color: #6e8a86 !important;
}
QMenuBar::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #ff6f61, stop:0.7 #14424a) !important;
    color: #ffffff !important;
}

/* ---------- popup: OPPOSITE diagonal to window ---------- */
QMenu {
    background: qlineargradient(x1:1, y1:0, x2:0.2, y2:1,
        stop:0 #0d2228, stop:0.6 #091a1f, stop:1 #0c161a) !important;
    border: 1px solid #1a4a52;
    border-radius: 7px;
    padding: 6px;
}
QMenu::item {
    padding: 6px 24px 6px 14px;
    border-radius: 4px;
    background: transparent !important;
    color: #d8e8e2 !important;
}
QMenu::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #c8f542, stop:0.55 #7d9c1e, stop:1 #14424a) !important;
    color: #0b1214 !important;
    font-weight: 600;
}
QMenu::item:disabled {
    color: #39494c !important;
}
QMenu::separator {
    height: 2px;
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff6f61, stop:1 #14424a) !important;
    margin: 6px 8px;
}

/* ---------- toolbar ---------- */
QToolBar {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0d2228, stop:1 #091a1f) !important;
    border-bottom: 1px solid #12333a;
    spacing: 3px;
    padding: 4px;
}
QToolBar::separator {
    background: #1a4a52;
    width: 2px;
    margin: 6px 4px;
}
QToolBar QToolButton {
    background: transparent !important;
    padding: 5px 8px;
    border-radius: 4px;
    color: #6e8a86 !important;
}
QToolBar QToolButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #c8f542, stop:1 #7d9c1e) !important;
    color: #0b1214 !important;
}
QToolBar QToolButton:checked, QToolBar QToolButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff6f61, stop:1 #ffb3a0) !important;
    color: #0b1214 !important;
}

/* ---------- buttons: steep skewed arc ---------- */
QPushButton {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #14424a, stop:0.4 #0e3238, stop:0.75 #12383c,
        stop:0.9 #16444a, stop:1 #0b1a1e) !important;
    border-radius: 6px;
    padding: 6px 18px;
    color: #d8e8e2 !important;
    font-weight: 600;
}
QPushButton:hover {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #c8f542, stop:0.5 #7d9c1e, stop:1 #2a4a10) !important;
    color: #0b1214 !important;
}
QPushButton:pressed {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #ffb3a0, stop:0.5 #ff6f61, stop:1 #8a2f26) !important;
    color: #0b1214 !important;
    padding: 7px 17px 5px 19px;
}
QPushButton:checked {
    background: qlineargradient(x1:0, y1:0, x2:0.85, y2:1,
        stop:0 #ff6f61, stop:0.6 #14424a, stop:1 #0b1a1e) !important;
    color: #ffb3a0 !important;
}
QPushButton:default {
    border-left: 3px solid #c8f542;
}
QPushButton:disabled {
    background: #0a161a !important;
    color: #39494c !important;
}

/* ---------- inputs: flat dark wells, chartreuse focus ---------- */
QLineEdit, QSpinBox, QDoubleSpinBox, QTextEdit, QPlainTextEdit {
    background-color: #06100f !important;
    border: 1px solid #12333a;
    border-left: 3px solid #12333a;
    border-radius: 4px;
    padding: 5px 8px;
    color: #c8f542 !important;
    selection-background-color: #14424a;
    selection-color: #c8f542;
}
QLineEdit:focus, QSpinBox:focus, QDoubleSpinBox:focus, QTextEdit:focus, QPlainTextEdit:focus {
    border-left: 3px solid #c8f542;
    background-color: #08181a !important;
}
QLineEdit:disabled, QSpinBox:disabled, QDoubleSpinBox:disabled,
QTextEdit:disabled, QPlainTextEdit:disabled {
    color: #39494c !important;
}
QSpinBox::up-button, QSpinBox::down-button,
QDoubleSpinBox::up-button, QDoubleSpinBox::down-button {
    background: transparent !important;
    border: none;
    width: 16px;
}

QComboBox {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0.4,
        stop:0 #0d2228, stop:1 #0b3236) !important;
    border: 1px solid #12333a;
    border-left: 3px solid #12333a;
    border-radius: 4px;
    padding: 5px 8px;
    color: #d8e8e2 !important;
}
QComboBox:hover {
    border-left: 3px solid #c8f542;
}
QComboBox:focus {
    border-left: 3px solid #ff6f61;
}
QComboBox::drop-down {
    border: none;
    background: transparent !important;
    width: 18px;
}
QComboBox QAbstractItemView {
    background: #0c161a !important;
    border: 1px solid #1a4a52;
    border-radius: 6px;
    padding: 4px;
    selection-background-color: #14424a;
    selection-color: #c8f542;
}
QComboBox:disabled {
    color: #39494c !important;
}

/* ---------- checkboxes: chartreuse-checked ---------- */
QCheckBox, QRadioButton {
    color: #d8e8e2 !important;
    background: transparent !important;
    padding: 3px;
}
QCheckBox::indicator, QRadioButton::indicator {
    width: 15px;
    height: 15px;
    background: #06100f !important;
    border: 1px solid #1a4a52;
    border-radius: 3px;
}
QRadioButton::indicator {
    border-radius: 8px;
}
QCheckBox::indicator:hover, QRadioButton::indicator:hover {
    border: 1px solid #c8f542;
}
QCheckBox::indicator:checked, QRadioButton::indicator:checked {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #c8f542, stop:1 #7d9c1e) !important;
    border: 1px solid #c8f542;
}

/* ---------- tabs: jagged mixed-axis pills ---------- */
QTabBar {
    background: transparent !important;
}
QTabBar::tab {
    background: transparent !important;
    color: #6e8a86 !important;
    padding: 7px 16px;
    border-radius: 4px;
    margin: 0 1px;
}
QTabBar::tab:hover {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #14424a, stop:1 #091a1f) !important;
    color: #c8f542 !important;
}
QTabBar::tab:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #14424a, stop:0.5 #1a4a52, stop:1 #c8f542) !important;
    color: #0b1214 !important;
    font-weight: 600;
}
QTabWidget::pane {
    border: 1px solid #12333a;
    background: #08181a !important;
}

/* ---------- docks: vertical sweep + clash edges ---------- */
QDockWidget {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #0c2228, stop:0.6 #091a1f, stop:1 #0b2620) !important;
    border: 1px solid #12333a;
}
QDockWidget::title {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #14424a, stop:0.75 #0e3238, stop:1 #ff6f61) !important;
    border-bottom: 2px solid #ff6f61;
    padding: 7px 10px;
    color: #ffffff !important;
    font-weight: 700;
}
QDockWidget::close-button, QDockWidget::float-button {
    background: transparent !important;
    border: none;
    padding: 2px;
    border-radius: 3px;
}
QDockWidget::close-button:hover, QDockWidget::float-button:hover {
    background: #ff6f61 !important;
}

/* ---------- group boxes ---------- */
QGroupBox {
    background: transparent !important;
    border: 1px solid #12333a;
    border-left: 3px solid #1a4a52;
    border-radius: 5px;
    margin-top: 14px;
    padding-top: 8px;
    font-weight: 600;
    color: #d8e8e2 !important;
}
QGroupBox::title {
    subcontrol-origin: margin;
    subcontrol-position: top left;
    padding: 0 7px;
    background: #0a1a1e !important;
    color: #c8f542 !important;
}

/* ---------- item views ---------- */
QAbstractItemView {
    background: #06100f !important;
    border: 1px solid #12333a;
    border-radius: 5px;
    alternate-background-color: #09191c;
    selection-background-color: #14424a;
    selection-color: #c8f542;
    outline: none;
}
QAbstractItemView::item {
    padding: 4px;
}
QAbstractItemView::item:hover {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #0e3238, stop:1 #14424a) !important;
}
QAbstractItemView::item:selected {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #14424a, stop:1 #1a4a52) !important;
    border-left: 3px solid #c8f542;
    color: #c8f542 !important;
}
QAbstractItemView::item:selected:!active {
    background: #0c2228 !important;
    border-left: 3px solid #12333a;
    color: #d8e8e2 !important;
}
QTreeView::branch {
    background: transparent !important;
}

QHeaderView::section {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:1,
        stop:0 #12383c, stop:1 #0b1a1e) !important;
    border: none;
    border-bottom: 2px solid #ff6f61;
    padding: 6px 8px;
    color: #ffb3a0 !important;
    font-weight: 600;
}

/* ---------- scrollbars: chartreuse handles ---------- */
QScrollBar:vertical {
    background: #06100f !important;
    width: 12px;
    margin: 0;
}
QScrollBar::handle:vertical {
    background: qlineargradient(x1:0, y1:0, x2:0, y2:1,
        stop:0 #c8f542, stop:0.5 #7d9c1e, stop:1 #14424a) !important;
    border-radius: 3px;
    min-height: 28px;
}
QScrollBar::handle:vertical:hover {
    background: #ff6f61 !important;
}
QScrollBar::add-line:vertical, QScrollBar::sub-line:vertical {
    height: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:vertical, QScrollBar::sub-page:vertical {
    background: #06100f !important;
}
QScrollBar:horizontal {
    background: #06100f !important;
    height: 12px;
    margin: 0;
}
QScrollBar::handle:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #c8f542, stop:0.5 #7d9c1e, stop:1 #14424a) !important;
    border-radius: 3px;
    min-width: 28px;
}
QScrollBar::handle:horizontal:hover {
    background: #ff6f61 !important;
}
QScrollBar::add-line:horizontal, QScrollBar::sub-line:horizontal {
    width: 0;
    background: none;
    border: none;
}
QScrollBar::add-page:horizontal, QScrollBar::sub-page:horizontal {
    background: #06100f !important;
}
QScrollBar::corner {
    background: #06100f !important;
}

/* ---------- sliders: coral-to-chartreuse sweep ---------- */
QSlider::groove:horizontal {
    background: #06100f !important;
    border: 1px solid #12333a;
    height: 5px;
    border-radius: 2px;
}
QSlider::sub-page:horizontal {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff6f61, stop:0.5 #c8f542, stop:1 #7d9c1e) !important;
    border-radius: 2px;
}
QSlider::handle:horizontal {
    background: #c8f542 !important;
    width: 12px;
    margin: -5px 0;
    border-radius: 6px;
}
QSlider::handle:horizontal:hover {
    background: #ff6f61 !important;
}

/* ---------- progress: full clash bar ---------- */
QProgressBar {
    background: #06100f !important;
    border: 1px solid #12333a;
    border-radius: 5px;
    text-align: center;
    color: #d8e8e2 !important;
    min-height: 15px;
}
QProgressBar::chunk {
    background: qlineargradient(x1:0, y1:0, x2:1, y2:0,
        stop:0 #ff6f61, stop:0.35 #c8f542, stop:0.65 #7d9c1e,
        stop:0.85 #14424a, stop:1 #c8f542) !important;
}

/* ---------- statusbar ---------- */
QStatusBar {
    background: qlineargradient(x1:1, y1:0, x2:0, y2:0,
        stop:0 #0d2228, stop:1 #081a1e) !important;
    border-top: 2px solid #c8f542;
    color: #6e8a86 !important;
}

/* ---------- tooltip ---------- */
QToolTip {
    background: #0c161a !important;
    border: 1px solid #c8f542;
    border-radius: 5px;
    padding: 6px 9px;
    color: #c8f542 !important;
}

/* ---------- splitters ---------- */
QSplitter::handle {
    background: #12333a !important;
}
QSplitter::handle:hover {
    background: #c8f542 !important;
}
